            bad += 1
            print('MISMATCH')
            print(json.dumps(req))
            print('got', json.dumps(g, sort_keys=True))
            print('exp', json.dumps(exp, sort_keys=True))
            if bad > 3:
                break
    print('cases', n, 'mismatches', bad)

