import json, random, sys
sys.path.insert(0,'/workspace/tmp')
from harness import run
from ref_replay import ref_replay

def make_case(rng):
    nn = rng.randint(1, 6)
    nodes = ['s%d' % i for i in range(nn)] + (['r'] if rng.random() < 0.8 else [])
    rng.shuffle(nodes)
    caps = {n: rng.randint(0, 3) for n in nodes}
    nf = rng.randint(1, 6)
    flows = []
    for i in range(nf):
        k = rng.randint(2, min(5, len(nodes)))
        path = rng.sample(nodes, k)
        H = rng.randint(8, 12)
        while True:
            kinds = list('KDZQT') + [rng.choice('KDZ') for _ in range(H-5)]
            rng.shuffle(kinds)
            if kinds.count('K') >= 1 and 4 + kinds.count('D') < H:
                break
        template = bytes(rng.randrange(256) for _ in range(H))
        labels = [rng.choice([16, 17, 100, 1048575]) for _ in path]
        flows.append({'id': 'f%d' % i, 'path': path, 'template': template.hex(),
                      'kinds': ''.join(kinds), 'labels': labels})
    events = []
    for _ in range(rng.randint(0, 40)):
        r = rng.random()
        if r < 0.3:
            f = rng.choice(flows)
            events.append({'op': 'put', 'flow': f['id'], 'node': rng.choice(f['path'])})
        elif r < 0.5:
            events.append({'op': 'enable', 'flow': rng.choice(flows)['id']})
        elif r < 0.6:
            events.append({'op': 'disable', 'flow': rng.choice(flows)['id']})
        elif r < 0.65:
            events.append({'op': 'reset'})
        else:
            f = rng.choice(flows)
            H = len(f['template']) // 2
            kinds = f['kinds']
            hb = bytearray(rng.randrange(256) for _ in range(H))
            p = rng.random()
            if p < 0.6:
                for pos, c in enumerate(kinds):
                    if c == 'K':
                        hb[pos] = int(f['template'][2*pos:2*pos+2], 16)
            if rng.random() < 0.2:
                hb[kinds.index('Q')] = rng.choice([7, 8, 9, 255, 0])
            if rng.random() < 0.7:
                hb[kinds.index('T')] = rng.choice([0, 1, 2, 3, len(f['path'])-1, len(f['path']), len(f['path'])+1, 255])
            payload = bytes(rng.randrange(256) for _ in range(rng.choice([0, 1, 5, 30])))
            events.append({'op': 'packet', 'flow': f['id'], 'header': bytes(hb).hex(),
                           'payload': payload.hex()})
    return {'mode': 'replay', 'capacities': caps, 'flows': flows, 'events': events}

def main():
    rng = random.Random(int(sys.argv[1]))
    n = int(sys.argv[2])
    reqs = [make_case(rng) for _ in range(n)]
    got = run(reqs)
    bad = 0
    for req, g in zip(reqs, got):
        exp = ref_replay(req)
        if g != exp:
            bad += 1
            print('MISMATCH')
            print(json.dumps(req))
            print('got', json.dumps(g, sort_keys=True))
            print('exp', json.dumps(exp, sort_keys=True))
            open('/workspace/tmp/bad_replay.json', 'w').write(json.dumps(req))
            if bad >= 2:
                break
    print('cases', n, 'mismatches', bad)

if __name__ == '__main__':
    main()
