cd /workspace && cat > tmp/diff.py << 'EOF'
def first_diff(got, exp, path=''):
    if type(got) is not type(exp):
        return '%s: type %r vs %r' % (path, type(got).__name__, type(exp).__name__)
    if isinstance(got, dict):
        if set(got) != set(exp):
            return '%s: keys %r vs %r' % (path, sorted(set(got)^set(exp)),)
        for k in got:
            d = first_diff(got[k], exp[k], path+'.'+str(k))
            if d: return d
        return None
    if isinstance(got, list):
        if len(got) != len(exp):
            return '%s: len %d vs %d' % (path, len(got), len(exp))
        for i,(a,b) in enumerate(zip(got,exp)):
            d = first_diff(a,b,path+'[%d]'%i)
            if d: return d
        return None
    return None if got == exp else '%s: %r vs %r' % (path, got, exp)
EOF
